class MySCFParameter(object):
    def __init__(self, app_version, dist_name, param_abbr, list_param, value):
        self.app_version = self._get_app_version(app_version)
        self.version = app_version
        self.dist_name = dist_name
        self.param_abbr = param_abbr
        self.list_param = list_param
        self.value = value

    def _get_app_version(self, app_version):
        for v in range(len(app_version)):
            if app_version[v] == '5':
                return str(app_version[v:])

    def __repr__(self):
        return "dist_name: {0} \n abbr: {1} \n value: {2} \n version: {3}".\
            format(self.dist_name, self.param_abbr, self.value, self.version)


@log_input_and_output
def get_objects_from_scf(path, as_dict=False):
    """
    Gets all objects from scf file.

    :param path: Path to SCF.xml, e.g. "/tmp/temp_scf.xml"
    :type path: str
    :param as_dict: If True, return dict with dist_name as key and dict with param abbr and value. Default is False.
    :type as_dict: bool
    :return: List of tuples of objects,
             e.g. [('MRBTS-50170/EQM-1/APEQM-1/RMOD-1', {'actPimCancellation': 'false'}),
                   ('MRBTS-50170/EQM-1/APEQM-1/RMOD-1', {'actSnapshotCollection': 'true'}),
                   ('MRBTS-50170', {'btsName': '50170'})]

            or dict with dist_name as key and dict with param abbr and value
            e.g. {'MRBTS-50170/EQM-1/APEQM-1/RMOD-1': {'actPimCancellation': 'false', 'actSnapshotCollection': 'true'},
                  MRBTS-50170': {'btsName': '50170'}}
    :rtype: list of obj or dict
    """

    scf_params = load_value_from_scf(path)
    if not as_dict:
        return [(element.dist_name, {element.param_abbr: element.value}) for element in scf_params]

    obj_dict = defaultdict(dict)
    for scf_managed_object in scf_params:
        obj_dict[scf_managed_object.dist_name][scf_managed_object.param_abbr] = scf_managed_object.value
    return obj_dict


@log_input_and_output
def get_file_name(file_name=None, validate_file_name=True, bts_type="GNB", second_gnb=False):
    """
    Gets scf file name, if file name is None select by sw_stream.
    Might be used for LTE SCF config files as well by providing bts_type parameter or for secondary gNB SCF config by
    set second_gnb on True.

    :param file_name: (Optional) Input file name
    :type file_name: (Default: None) str
    :param validate_file_name: (Optional) Defines if provided file name should be validated
    :param validate_file_name: (Default: True) bool
    :param bts_type: BTS type 5G (GNB) or LTE (ENB)
    :type bts_type: (Default: GNB) str
    :param second_gnb: True if operation concerns secondary gNB SMOD, False otherwise; defaults to False.
    :type second_gnb: boolean
    :return: File name
    :rtype: str
    """
    if validate_file_name:
        return file_name if _is_file_name_valid(file_name, bts_type=bts_type) else _get_scf_file_name(bts_type,
                                                                                                      second_gnb)

    return file_name if file_name else _get_scf_file_name(bts_type)


@log_input_and_output
def get_full_path_to_base_scf(scf_file_path=None, bts_type='GNB', second_gnb=False):
    """
        Gets full base scf file absolute path. If scf_file_path is None,
        then scf file will be automatically selected from TesLine repo directory, based on testline name,
        current SW stream, chosen BTS type and chosen second_gnb parameter.

        :param scf_file_path: (Optional) Full absolute SCF file path (with xml extension).
        :type scf_file_path: (Default: None) str
        :param bts_type: (Optional - It is only taken into account if scf_file_path is None)
                         BTS type 'GNB' or 'ENB' of which the smods config should be returned; default: 'GNB'.
        :type bts_type: (Default: 'GNB') str
        :param second_gnb: True if operation concerns secondary gNB SMOD, False otherwise; defaults to False.
        :type second_gnb: boolean
        :return: Full SCF file absolute path (including xml extension)
        :rtype: str
        """
    if scf_file_path is None:
        return os.path.join(get_path_to_scf_dir(bts_type=bts_type), get_file_name(bts_type=bts_type,
                                                                                  second_gnb=second_gnb))
    check_if_scf_path_exists(scf_file_path=scf_file_path)
    return scf_file_path


@log_input_and_output
def get_full_path_to_custom_scf(custom_scf_name, bts_type='GNB'):
    """
    Gets full absolute path to custom scf file. Scf file will be automatically selected from TesLine repo directory,
    based on testline name, current SW stream and chosen BTS type.

    :param custom_scf_name: name of SCF file (without xml extension)
    :type custom_scf_name: str
    :param bts_type: BTS type 'GNB' or 'ENB' of which the smods config should be returned; default: 'GNB'.
    :type bts_type: str
    :return: full SCF file absolute path (including xml extension)
    :rtype: str
    """
    return os.path.join(get_path_to_scf_dir(bts_type=bts_type), "custom", custom_scf_name + ".xml")


@log_input_and_output
def check_if_scf_path_exists(scf_file_path):
    """
        Checks if provided SCF file path exists. If not, FileDoesNotExist exception will be raised.

        :param scf_file_path: Full absolute SCF file path (with xml extension).
        :type scf_file_path: str
        :raises FileDoesNotExist when SCF file path does not exist.
        """
    if not os.path.isfile(scf_file_path):
        raise FileDoesNotExist("SCF file path {} doesn't exist.".format(scf_file_path))


@log_input_and_output
def get_scf_file_name_from_full_path(scf_file_path):
    """
        Gets SCF file name prom provided full absolute SCF file path.

        :param scf_file_path: Full absolute SCF file path (with xml extension).
        :type scf_file_path: str
        :return: Name of SCF file (with extension)
        :rtype: str
        """
    return os.path.basename(scf_file_path)


