def is_full_path_to_scf(scf: str) -> bool:
    """
    Checks if provided SCF is full path to SCF file (with xml extension).
    :param scf: full path to SCF file (with xml extension) or custom SCF name, e.g. "/tmp/temp_scf.xml"
    :type scf: str
    :return: True if provided SCF is full path to SCF file (with xml extension), False otherwise
    :rtype: bool
    """
    return scf.lower().endswith('.xml')


def validate_scf_file_parameters(scf_path, custom_parameters_to_validate=None, bts_type="GNB"):
    """
    Validates parameters in provided scf file. Logs warnings in case of parameters having unexpected values.
    Custom parameter should belong to one of the following categories:
        - parameters that should have specific value
        - parameters that should have minimum value
        - parameters that should have maximum value
    :param scf_path: full path to scf file (with xml extension), e.g. "/tmp/temp_scf.xml"
    :type scf_path: str
    :param custom_parameters_to_validate: custom parameters that should be validated. If their value is incorrect,
                                          a warning will be logged; e.g.:
                                          {'specific_value': [{'param_name': 'actSth', 'dist_name': 'MRBTS-{}/MNL-1',
                                                               'param_value': 'false', 'custom_warning': 'custom'}],
                                           'min_value': [{'param_name': 'nsaInactivityTimer',
                                                          'dist_name': 'MRBTS-{}/NRBTS-{}', 'param_value': 60,
                                                          'custom_warning': None}],
                                           'max_value': []};
                                          defaults to None (default parameters for GNB will be checked)
    :type custom_parameters_to_validate: dict or None
    :param bts_type: type of bts, can be GNB or ENB; if bts type is ENB, custom_parameters_to_validate should be set;
                     defaults to GNB
    :type bts_type: str
    """
    parameters = custom_parameters_to_validate if custom_parameters_to_validate else PARAMETERS_TO_VALIDATE

    for param in parameters.get('specific_value'):
        _check_if_parameter_has_specific_value(
            param_name=param['param_name'],
            dist_name=ConfigOperations.adjust_distname(dist_name=param['dist_name'], bts_type=bts_type),
            scf_path=scf_path,
            specific_value=param['param_value'],
            custom_warning=param['custom_warning']
        )

    for param in parameters.get('min_value'):
        _check_if_parameter_has_min_value(
            param_name=param['param_name'],
            dist_name=ConfigOperations.adjust_distname(dist_name=param['dist_name'], bts_type=bts_type),
            scf_path=scf_path,
            min_value=param['param_value'],
            custom_warning=param['custom_warning']
        )

    for param in parameters.get('max_value'):
        _check_if_parameter_has_max_value(
            param_name=param['param_name'],
            dist_name=ConfigOperations.adjust_distname(dist_name=param['dist_name'], bts_type=bts_type),
            scf_path=scf_path,
            max_value=param['param_value'],
            custom_warning=param['custom_warning']
        )


@log_input_and_output
def _check_if_parameter_has_min_value(param_name, dist_name, scf_path, min_value, custom_warning=None):
    """
    Checks if value of given parameter isn't below required value. If it is below given value, then warning is logged.
    :param param_name: parameter name, e.g. 'srbInactivityTimerSA'
    :type param_name: str
    :param dist_name: Path to MOC (managed object class) under which the parameter is located, e.g. "MRBTS-507/NRBTS-1"
    :type dist_name: str
    :param scf_path: full path to scf file (with xml extension), e.g. "/tmp/temp_scf.xml"
    :type scf_path: str
    :param min_value: minimum value for parameter which will be checked
    :type min_value: int or str
    :param custom_warning: custom warning message which will be logged. Defaults to None (default message will be
                           logged).
    :type custom_warning: str or None
    :return: True if parameter has valid minimal value, False otherwise.
    :rtype: bool
    """
    moc_obj = _get_obj_from_scf(dist_name=dist_name, path=scf_path)
    param_value = _get_value_of_param_from_obj(obj=moc_obj, param_abbr=param_name)

    if int(param_value) < int(min_value):
        default_message = (f"Parameter {param_name} ({dist_name}) shouldn't have value below {min_value}. "
                           f"Actual value of {param_name}: {param_value}.")
        message = custom_warning if custom_warning else default_message
        log_warning(message)
        return False
    return True


@log_input_and_output
def _check_if_parameter_has_max_value(param_name, dist_name, scf_path, max_value, custom_warning=None):
    """
    Checks if value of given parameter isn't above required value. If it is above given value, then warning is logged.
    :param param_name: parameter name, e.g. 'srbInactivityTimerSA'
    :type param_name: str
    :param dist_name: Path to MOC (managed object class) under which the parameter is located, e.g. "MRBTS-507/NRBTS-1"
    :type dist_name: str
    :param scf_path: full path to scf file (with xml extension), e.g. "/tmp/temp_scf.xml"
    :type scf_path: str
    :param max_value: maximum value for parameter which will be checked
    :type max_value: int or str
    :param custom_warning: custom warning message which will be logged. Defaults to None (default message will be
                           logged).
    :type custom_warning: str or None
    :return: True if parameter has valid maximum value, False otherwise.
    :rtype: bool
    """
    moc_obj = _get_obj_from_scf(dist_name=dist_name, path=scf_path)
    param_value = _get_value_of_param_from_obj(obj=moc_obj, param_abbr=param_name)

    if int(param_value) > int(max_value):
        default_message = (f"Parameter {param_name} ({dist_name}) shouldn't have value above {max_value}. "
                           f"Actual value of {param_name}: {param_value}.")
        message = custom_warning if custom_warning else default_message
        log_warning(message)
        return False
    return True


@log_input_and_output
def _check_if_parameter_has_specific_value(param_name, dist_name, scf_path, specific_value, custom_warning=None):
    """
    Checks if value of given parameter has required value. If it is not equal to given value, then warning is logged.
    :param param_name: parameter name, e.g. 'srbInactivityTimerSA'
    :type param_name: str
    :param dist_name: Path to MOC (managed object class) under which the parameter is located, e.g. "MRBTS-507/NRBTS-1"
    :type dist_name: str
    :param scf_path: full path to scf file (with xml extension), e.g. "/tmp/temp_scf.xml"
    :type scf_path: str
    :param specific_value: required value for parameter which will be checked
    :type specific_value: int or str
    :param custom_warning: custom warning message which will be logged. Defaults to None (default message will be
                           logged).
    :type custom_warning: str or None
    :return: True if parameter has required value, False otherwise.
    :rtype: bool
    """
    moc_obj = _get_obj_from_scf(dist_name=dist_name, path=scf_path)
    param_value = _get_value_of_param_from_obj(obj=moc_obj, param_abbr=param_name)

    if str(param_value) != str(specific_value):
        default_message = (f"Parameter {param_name} ({dist_name}) should have value equal to {specific_value}. "
                           f"Actual value of {param_name}: {param_value}.")
        message = custom_warning if custom_warning else default_message
        log_warning(message)
        return False
    return True


def _validate_radio_modules_protocol_param_exists(scf_path, bts_id):
    """
    Validates if radio modules protocol parameter exists in provided scf file.
    :param scf_path: full path to scf file (with xml extension), e.g. "/tmp/temp_scf.xml"
    :type scf_path: str
    :param bts_id: BTS ID of station from which user wants to get parameter value.
    :type bts_id: str
    """
    radio_modules = _get_radio_modules_objects(scf_path=scf_path, bts_id=bts_id)
    rmod_id_missing_protocol = []
    for rmod_dn, rmod_params in radio_modules.items():
        if 'protocol' not in rmod_params:
            rmod_id_missing_protocol.append(rmod_dn.rsplit('-', 1)[-1])

    if rmod_id_missing_protocol:
        log_warning(f"Radio modules with following CONFIG IDs are missing `protocol` parameter: "
                    f"{sorted(rmod_id_missing_protocol, key=int)}.")


@log_input_and_output
def _get_list_of_object_ids(scf_path, object_name):
    """
    Get list of IDs for defined object from provided file.
    :param scf_path: full path to scf file (with xml extension), e.g. "/tmp/temp_scf.xml"
    :type scf_path: str
    :param object_name: name of particular object, for example "MRBTS", "SMOD", "BBMOD", "NRCELL", "LNCEL", etc.
    :type object_name: str
    :return: sorted list of strings with object ids without duplicates, returns empty list if no object could
             be found. Example output:
             ['501', '502', '503', '504', '505', '506']
    :rtype: list(str)
    """
    with open(scf_path, 'r+') as f:
        xml = f.read()
        rule = r"(?<=%s-)([0-9]{1,5})" % object_name
        result_list = re.findall(rule, xml)
        object_id_list = list(set(result_list))
        object_id_list.sort()
        return object_id_list


@log_input_and_output
def _convert_list_to_single_value_if_possible(input_list):
    """
    Converts input list in case of one element listr or empty list. Otherwise returns input list without any changes.
    :param input_list: list of strings
    :type input_list: list
    :return: list of strings if provided input_list has more than one element (provided input_list is returned
             with no changes), string if provided list has one element, None if provided list is empty
    :rtype: list(str) or str or None
    """
    if input_list:
        return input_list[0] if len(input_list) == 1 else input_list
    return None


@log_input_and_output
def check_whether_GPS_exists(connection):
    """
    Check whether Test Line contains GPS
    :param connection: Session to use, can be an alias or SessionHandler object
    :type connection: str/SessionHandler object
    :return: True if GPS exist, False otherwise
    :rtype Boolean
    """
    admin().get_current_scf_file(local_dir_path='/tmp', file_name='scf_gps.xml', timeout=30, connection=connection)

    scf_params = load_value_from_scf(path='/tmp/scf_gps.xml')
    for scf_param in scf_params:
        if scf_param.param_abbr == 'syncInputType':
            if scf_param.value == '1pps/ToD from external GNSS receiver':
                return True
    return False


def _is_file_name_valid(file_name, bts_type):
    list_of_scf = _get_list_of_scf(bts_type)

    if file_name is None:
        return False
    if file_name in list_of_scf:
        return True
    raise FileDoesNotExist("Scf file: {} doesn't exist. List of scfs: {}.".format(file_name, list_of_scf))


@log_input_and_output
def _get_radio_protocol_type(scf_path, bts_id, rmod_id):
    """
    Gets radio protocol type from provided scf.

    example:look for manageObjects with pattern: MRBTS-1/EQM_R-1/APEQM_R-1/RMOD_R-x
            find appropriate object for related rmod id:<p name="configDN">MRBTS-1/EQM-1/APEQM-1/RMOD-1</p>
            read value from:<p name="l3Protocol">CPRI_RP-1</p>

    :param scf_path: Full path to scf file (with xml extension), e.g. "/tmp/temp_scf.xml"
    :type scf_path: str
    :param bts_id: BTS ID of station from which user wants to get parameter value.
    :type bts_id: str
    :param rmod_id: Rmod id from which user wants to get parameter value.
    :type rmod_id: str | int
    :return: Radio protocol type. Empty string when not detected
    :rtype: str
    """
    objects = get_objects_from_scf(scf_path)
    dist_name = None
    for elem in objects:
        if re.match(rf'MRBTS-{bts_id}/EQM_R-\d+/APEQM_R-\d+/RMOD_R-\d+$', elem[0]) and 'configDN' in elem[1]:
            if elem[1]['configDN'].split("-")[-1] == str(rmod_id):
                dist_name = elem[0]
                break
    for elem in objects:
        if dist_name == elem[0] and 'l3Protocol' in elem[1]:
            return elem[1]['l3Protocol']
    return ""


@log_input_and_output
def _get_radio_modules_objects(scf_path, bts_id):
    """
    Gets radio modules objects from provided scf.

    :param scf_path: Full path to scf file (with xml extension), e.g. "/tmp/temp_scf.xml"
    :type scf_path: str
    :param bts_id: BTS ID of station from which user wants to get parameter value.
    :type bts_id: str
    :return: Dict of radio modules objects
    :rtype: dict
    """
    objects = get_objects_from_scf(scf_path, as_dict=True)
    radio_modules = {}
    for dist_name, params in objects.items():
        if re.match(rf'MRBTS-{bts_id}/EQM-1/APEQM-1/RMOD-\d+$', dist_name):
            radio_modules[dist_name] = params
    return radio_modules


@log_input_and_output
def _choose_correct_local_cell_name(cell_id, cell_name, cell_type='nr'):
    """
    Local cell name differs according to existence of cellName parameter of provided cell.
    Method returns correct local cell name according to provided parameters.

    :param cell_id: Cell id of cell from which user wants to choose correct local cell name.
    :type cell_id: str
    :param cell_name: 'cellName' parameter read from cell object in scf.
    :type cell_name: str
    :param cell_type: cell type of given RAT: "nr" or "lte", default set "nr"
    :type cell_type: str
    :return: Correct local cell name according to provided parameters.
    :rtype: str
    :raises RatNotSupported: when type of cell is is not supported (cell_type different than nr or lte).
    """
    cell_obj = _get_cell_object_and_validate_rat(cell_type)
    if cell_type == 'nr' and cell_name:
        return 'NRCELL-{0} ({1})'.format(cell_id, cell_name)
    elif cell_type == 'lte' and cell_name:
        return cell_name
    return '{0}-{1}'.format(cell_obj, cell_id)


@log_input_and_output
def _check_scf(scf_path, should_contain):
    """
    This method allows to check scf file whether contain all objects required by SiSo.

    :param scf_path: Full path to scf file (with xml extension), e.g. "/tmp/temp_scf.xml"
    :type scf_path: str
    :param should_contain: List of scf objects (dict). Dict should contain "dist_name",
                            "param_abbr" and "value" are optional, but "param_abbr" can not exist without "value".
        Example:
             should_contain = [{"dist_name": "MRBTS-1/NRBTS-1", "param_abbr": "shutdownNoX2TrafficTmr", "value": "0"},
                               {"dist_name": "MRBTS-1/NRBTS-1", "param_abbr": "enDcX2SetupReqTmr", "value": "30"},
                               {"dist_name": "MRBTS-1/NRBTS-1", "param_abbr": "maxX2EnDcCfUpRetry", "value": "2"},
                               {"dist_name": "MRBTS-1/NRBTS-1"},
                               {"dist_name": "MRBTS-1/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV6-1"}]
    :type should_contain: list of dicts
    :raises MissingMandatoryObject: when missing mandatory object in scf.
    """
    errors = []
    scf_params_from_list = load_value_from_scf(scf_path)

    for obj in should_contain:
        for scf_param in scf_params_from_list:
            if scf_param.dist_name == obj.get("dist_name"):
                if obj.get("param_abbr") is not None:
                    if scf_param.param_abbr == obj.get('param_abbr') and scf_param.value == obj.get("value"):
                        break
                else:
                    break
        else:
            msg = "Missing object in SCF which is required by SiSo WoW. Dist name: {}".format(obj.get("dist_name"))
            if obj.get("param_abbr") is not None:
                errors.append("{}, Param abbr: {}, Value: {}".format(msg, obj.get('param_abbr'), obj.get('value')))
            else:
                errors.append(msg)
    if errors:
        raise MissingMandatoryObject(errors)


@log_input_and_output
def _check_and_adjust_given_param_in_scf(class_name, dist_name, param_abbr, value, scf_path):
    scf_params_from_list = load_value_from_scf(scf_path)

    for scf_param in scf_params_from_list:
        if scf_param.dist_name == dist_name:
            if param_abbr is not None:
                if scf_param.param_abbr == param_abbr and scf_param.value != value:
                    log_deprecation("Param: {} should have value: {}, actual value: {}. "
                                    "Fix it immediately!!!".format(param_abbr, value, scf_param.value))
                    ul_scf().prepare_scf_file(scf_path=scf_path,
                                              should_not_contain=[dict(dist_name=scf_param.dist_name,
                                                                       p_name=scf_param.param_abbr)])
                    ul_scf().prepare_scf_file(scf_path=scf_path,
                                              should_contain=[dict(dist_name=scf_param.dist_name,
                                                                   class_name=class_name,
                                                                   version=scf_param.version,
                                                                   p_name=scf_param.param_abbr,
                                                                   value=value,
                                                                   operation='create')])
                    break
            else:
                break


@log_input_and_output
def _get_value_of_param_from_obj(obj, param_abbr):
    for param in obj.parameters:
        if param.name == param_abbr:
            return param.value


@log_input_and_output
def _get_obj_from_scf(dist_name, path):
    scf_model = SCFFactory(path).get_scf_model()
    for scf_managed_object in scf_model.managed_objects:
        if scf_managed_object.dist_name == dist_name:
            return scf_managed_object


@log_input_and_output
def _get_bts_id_and_ip_address_from_init(tl_config, bts_type="GNB", setup_mode="NSA"):
    if bts_type.upper() == "GNB":
        instance_id, ip_address = _get_bts_id_and_ip_address_from_init_for_gnb(tl_config, setup_mode)
    elif bts_type.upper() == "ENB":
        instance_id, ip_address = _get_bts_id_and_ip_address_from_init_for_enb(tl_config, setup_mode)

    if instance_id is None:
        raise Exception("Please make sure that your data is correct in init file.")

    return instance_id, ip_address


@log_input_and_output
def _get_bts_id_and_ip_address_from_init_for_gnb(tl_config, setup_mode):
    instance_id = tl_config.gnbs[0].instance_id
    if "NSA" in setup_mode:
        x2c = tl_config.gnbs[0].cu.x2c
        ip_address = x2c.v6 or x2c.v4
        return instance_id, ip_address

    return instance_id, None


@log_input_and_output
def _get_bts_id_and_ip_address_from_init_for_enb(tl_config, setup_mode):
    instance_id = tl_config.enbs[0].instance_id
    if "NSA" in setup_mode:
        x2c = tl_config.enbs[0].x2_link_addr
        ip_address = x2c.v6 or x2c.v4
        return instance_id, ip_address

    return instance_id, None


@log_input_and_output
def _get_nrbts_id_from_init(tl_config, bts_type="GNB"):
    if bts_type.upper() == "GNB":
        return tl_config.gnbs[0].global_bts_id
    elif bts_type.upper() == "ENB":
        return tl_config.enbs[0].global_bts_id

    raise IncorrectBTSType("BTS type should be GNB or ENB.")


@log_input_and_output
def _build_moc_ip(global_bts_id, ip_addr, ip_type, prefix, scf_file_path):
    dist_name = 'MRBTS-{}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/{}-1'.format(str(global_bts_id), ip_type)
    class_name = 'com.nokia.srbts.tnl:{}'.format(ip_type)
    version = get_param_from_scf(path=scf_file_path, dist_name=dist_name)

    return [dict(dist_name=dist_name,
                 class_name=class_name,
                 version=version,
                 p_name='ipAddressAllocationMethod',
                 value='MANUAL',
                 operation='create'),
            dict(dist_name=dist_name,
                 class_name=class_name,
                 version=version,
                 p_name='localIpAddr',
                 value=str(ip_addr),
                 operation='create'),
            dict(dist_name=dist_name,
                 class_name=class_name,
                 version=version,
                 p_name='localIpPrefixLength',
                 value=str(prefix),
                 operation='create')]


@log_input_and_output
def _get_moc_mplanenw(bts_id, path):
    mplanenw_obj = _get_obj_from_scf(dist_name='MRBTS-{}/MNL-1/MNLENT-1/MPLANENW-1'.format(bts_id), path=path)
    for mplanenw_param in mplanenw_obj.parameters:
        if mplanenw_param.name == "mPlaneIpv4AddressDN" or mplanenw_param.name == "mPlaneIpv6AddressDN":

            mplane_ip = _get_obj_from_scf(dist_name=mplanenw_param.value, path=path)
            class_name = 'com.nokia.srbts.tnl:{}'.format(mplane_ip.moc_name.split('/')[-1])

            return [dict(dist_name=mplane_ip.dist_name,
                         class_name=class_name,
                         version=mplane_ip.version,
                         p_name='ipAddressAllocationMethod',
                         value=str(_get_value_of_param_from_obj(mplane_ip, 'ipAddressAllocationMethod')),
                         operation='create'),
                    dict(dist_name=mplane_ip.dist_name,
                         class_name=class_name,
                         version=mplane_ip.version,
                         p_name='localIpAddr',
                         value=str(_get_value_of_param_from_obj(mplane_ip, 'localIpAddr')),
                         operation='create'),
                    dict(dist_name=mplane_ip.dist_name,
                         class_name=class_name,
                         version=mplane_ip.version,
                         p_name='localIpPrefixLength',
                         value=str(_get_value_of_param_from_obj(mplane_ip, 'localIpPrefixLength')),
                         operation='create')]


@log_input_and_output
def _get_scf_name(second_gnb=False):
    hostname = socket.gethostname()
    try:
        return hostname.split('CLOUD')[1] if not second_gnb else f"{hostname.split('CLOUD')[1]}_2"
    except IndexError:
        return hostname.split('SISO')[1] if not second_gnb else f"{hostname.split('SISO')[1]}_2"


@log_input_and_output
def _is_scf_file_name_valid(scf_file_name):
    """
    Checks whether given SCF file name is valid.

    New way:
        Examples of valid SCF file names:
            * SCF_1300T00_5G20B.xml
            * SCF_SISOAUTO017_master.xml
        Examples of invalid SCF file names:
            * SCF_1200T05_5GC001821-2_5G21A.xml

    :param scf_file_name: name of SCF file (with extension) which will be checked
    :type scf_file_name: str
    :return: True if SCF file name is valid, False otherwise.
    :rtype: bool
    """
    stream_pattern = r'_(master)*(SBTS_master)*(5G[0-9]{2}[A-Z]{1})*(SBTS[0-9]{2}[A-Z]{1}[0-9]?)*\.xml$'
    list_of_accepted_scf_patterns = [
        r'^SCF_[0-9]{4}T[0-9]{2}' + stream_pattern,
        r'^SCF_[0-9]{4}T[0-9]{2}_2' + stream_pattern,
        r'^SCF_[0-9]{4}T[0-9]{2}_LTE' + stream_pattern,
        r'^SCF_CLOUD[0-9]{3}' + stream_pattern,
        r'^SCF_CLOUD[0-9]{5}' + stream_pattern,
        r'^SCF_CLOUD[0-9]{3}_2' + stream_pattern,
        r'^SCF_SISOAUTO[0-9]{3}' + stream_pattern,
        r'^SCF_SISOAUTO[0-9]{3}_2' + stream_pattern,
        r'^SCF_SISOBENCH[0-9]{3}' + stream_pattern,
        r'^SCF_SISOBENCH[0-9]{3}_2' + stream_pattern,
        r'^SCF_SISOBENCH[0-9]{3}_LTE' + stream_pattern,
        r'^SCF_SISOMANUAL[0-9]{3}' + stream_pattern,
        r'^SCF_SISOMANUAL[0-9]{3}_2' + stream_pattern,
        r'^SCF_SISOMANUAL[0-9]{3}_LTE' + stream_pattern,
        r'^SCF_SISOAUTO[0-9]{3}_LTE' + stream_pattern,
        r'^SCF_T[0-9]{1}SK[0-9]{3}' + stream_pattern,
    ]
    for pattern in list_of_accepted_scf_patterns:
        if re.match(pattern, scf_file_name):
            return True
    return False


@log_input_and_output
def _get_scf_file_name(bts_type="GNB", second_gnb=False):
    if bts_type.upper() == "GNB" or bts_type.upper() == "ENB":
        sw_stream = get_sw_stream_with_translated_master(bts_type=bts_type)
        list_of_scf = _get_list_of_scf(bts_type)
        sw_streams = _get_sw_streams(list_of_scf)

        if sw_stream in sw_streams:
            return _get_scf_file_name_from_list(list_of_scf, sw_stream, bts_type=bts_type, second_gnb=second_gnb)
        else:
            raise SwStreamDoseNotExist(
                "SW stream: {} doesn't exist in SW streams: {}.".format(
                    sw_stream, sw_streams
                )
            )
    else:
        raise IncorrectBTSType("BTS type should be GNB or ENB.")


def _get_list_of_scf(bts_type):
    return os.listdir(get_path_to_scf_dir(bts_type=bts_type))


@log_input_and_output
def _get_sw_streams(list_of_scf):
    sw_streams = set()
    for scf_name in list_of_scf:
        if _is_scf_file_name_valid(scf_name):
            split_scf = scf_name.split('_')
            if split_scf[-2] == "SBTS":
                sw_streams.add("{}_{}".format(split_scf[-2], split_scf[-1].rstrip('.xml')))
            sw_streams.add(split_scf[-1].rstrip('.xml'))
    return sw_streams


@log_input_and_output
def _get_scf_file_name_from_list(list_of_scf, sw_stream=None, bts_type="GNB", second_gnb=False):
    """
    Searches through list of SCF file names for one which matches given TL name and SW stream.
    Skips invalid SCF file names during search.

    :param list_of_scf: all available SCF file names
    :type list_of_scf: list(str)
    :param sw_stream: SW stream name i.e. 'master' or '5G21A'
    :type sw_stream: str
    :param bts_type: BTS type 5G ("GNB") or LTE ("ENB")
    :type bts_type: (Default: "GNB") str
    :return: matching SCF file name, i.e. 'SCF_1800T09_RealCore_5G21A.xml'
    :rtype: str
    :raise FileDoesNotExist: when no matching SCF file name could be found
    """
    name = _get_scf_name(second_gnb=second_gnb)
    scf_exception_5g = FileDoesNotExist("File witch contain: {} and {} doesn't exist.".format(name, sw_stream))
    scf_exception_4g = FileDoesNotExist("File witch contain: {}_LTE doesn't exist.".format(name))

    for scf_name in list_of_scf:
        if not _is_scf_file_name_valid(scf_name):
            continue
        if bts_type == "GNB":
            if name in scf_name and sw_stream in scf_name:
                return scf_name
        if bts_type == "ENB":
            if name in scf_name and "_LTE" in scf_name and sw_stream in scf_name:
                return scf_name
    else:
        raise scf_exception_5g if bts_type == "GNB" else scf_exception_4g


@log_input_and_output
def _get_bts_setup_mode(connection):
    adm = admin()
    try:
        return adm.get_bts_info(connection=connection)["gNbCuType"]
    except KeyError:
        return "SA"


@log_input_and_output
def _get_cell_object_and_validate_rat(cell_type):
    """
    Gets cell object name for particular cell type

    :param cell_type: One of following types: "nr" or "lte"
    :type cell_type: str
    :return: object name according to provided cell type
    :rtype: str
    :raise RatNotSupported: when given RAT technology (cell_type) is not supported.
    """
    if cell_type == 'nr':
        return 'NRCELL'
    elif cell_type == 'lte':
        return 'LNCEL'
    else:
        raise RatNotSupported("RAT {} is currently not supported".format(cell_type))


@log_input_and_output
def _get_mandatory_x2_link_parameters_list(bts_type, global_bts_id, nrbts_id):

    if bts_type.upper() == "GNB":
        return ([{"dist_name": "MRBTS-{0}/NRBTS-{1}".format(global_bts_id, nrbts_id),
                  "param_abbr": "shutdownNoX2TrafficTmr",
                  "value": "0"},
                 {"dist_name": "MRBTS-{0}/NRBTS-{1}".format(global_bts_id, nrbts_id),
                  "param_abbr": "enDcX2SetupReqTmr",
                  "value": "30"},
                 {"dist_name": "MRBTS-{0}/NRBTS-{1}".format(global_bts_id, nrbts_id),
                  "param_abbr": "maxX2EnDcCfUpRetry",
                  "value": "2"}
                 ])
    elif bts_type.upper() == "ENB":
        return ([{"dist_name": "MRBTS-{0}/LNBTS-{1}".format(global_bts_id, nrbts_id),
                  "param_abbr": "maxX2CfUpRetry",
                  "value": "5"}
                 ])
